// Parses what a user typed in the amount field and returns integer cents.
// Accepts: digits, optionally a dot and 1 or 2 decimals, surrounding spaces.
//   "12" -> 1200, "12.5" -> 1250, " 7.10 " -> 710
// Throws an Error for: empty input, zero, negatives, letters,
// commas and more than 2 decimals.
function parseAmount(input) {
  const text = String(input).trim();
  if (!/^\d+(\.\d{1,2})?$/.test(text)) {
    throw new Error(`Not a valid amount: "${input}"`);
  }
  const [whole, fraction = ''] = text.split('.');
  const cents = Number(whole) * 100 + Number(fraction.padEnd(2, '0'));
  if (cents === 0) throw new Error('Amount must be greater than zero');
  return cents;
}

