describe('parseAmount', () => {
  test.each([
    ['12', 1200],
    ['12.5', 1250],
    ['12.50', 1250],
    ['0.01', 1],
    [' 7.10 ', 710],
  ])('parses %s as %i cents', (input, cents) => {
    expect(parseAmount(input)).toBe(cents);
  });

  test.each(['', 'ten', '-5', '1,000', '12.505'])('rejects %s', (input) => {
    expect(() => parseAmount(input)).toThrow();
  });

  test.each(['0', '0.00'])('rejects a zero amount: %s', (input) => {
    expect(() => parseAmount(input)).toThrow('greater than zero');
  });
});
